-- Importacao gerada a partir de Imobilizado Richesse.xlsx.
-- Rode este arquivo no SQL Editor do Supabase depois das migrations.
-- Seguro para rodar novamente: usa upsert por asset_code.

begin;

select 'Brasília', 'loja', null where not exists (select 1 from locations where name = 'Brasília') union all
select 'Flamboyant', 'loja', null where not exists (select 1 from locations where name = 'Flamboyant') union all
select 'Goiânia Shopping', 'loja', null where not exists (select 1 from locations where name = 'Goiânia Shopping') union all
select 'Marista', 'loja', null where not exists (select 1 from locations where name = 'Marista') union all
select 'Oeste', 'loja', null where not exists (select 1 from locations where name = 'Oeste') union all
select 'Prime', 'loja', null where not exists (select 1 from locations where name = 'Prime') union all
select 'Togo', 'loja', null where not exists (select 1 from locations where name = 'Togo');

select 'Computadores e Periféricos', 'Monitor', '#2563eb' where not exists (select 1 from categories where name = 'Computadores e Periféricos') union all
select 'Máquinas e Equipamentos', 'Cog', '#f59e0b' where not exists (select 1 from categories where name = 'Máquinas e Equipamentos') union all
select 'Móveis e Utensílios', 'Armchair', '#64748b' where not exists (select 1 from categories where name = 'Móveis e Utensílios') union all
select 'Veículos', 'Truck', '#ef4444' where not exists (select 1 from categories where name = 'Veículos');

create temp table import_imobilizado_richesse (asset_code text, name text, serial_number text, category_name text, location_name text, acquisition_value numeric, notes text) on commit drop;


  asset_code, name, serial_number, category_id, location_id, status,
  acquisition_value, notes, qr_code, updated_at
)
select
  i.asset_code,
  i.name,
  nullif(i.serial_number, ''),
  c.id,
  l.id,
  'operacional',
  i.acquisition_value,
  i.notes,
  i.asset_code,
  now()
from import_imobilizado_richesse i
left join categories c on c.name = i.category_name
left join locations l on l.name = i.location_name
on conflict (asset_code) do update set
  name = excluded.name,
  serial_number = excluded.serial_number,
  category_id = excluded.category_id,
  location_id = excluded.location_id,
  acquisition_value = excluded.acquisition_value,
  notes = excluded.notes,
  qr_code = excluded.qr_code,
  updated_at = now();

commit;

